def countPalindromePairs(words):
    ws = words.split(",")
    index = {w: i for i, w in enumerate(ws)}
    count = 0
    for i, w in enumerate(ws):
        n = len(w)
        for k in range(n + 1):
            left, right = w[:k], w[k:]
            if left == left[::-1]:
                j = index.get(right[::-1])
                if j is not None and j != i:
                    count += 1
            if right and right == right[::-1]:
                j = index.get(left[::-1])
                if j is not None and j != i:
                    count += 1
    return count
